INSERT OR REPLACE INTO ec_page_about ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "cta_title", "cta_sub", "heading", "heading_accent", "intro", "headshot", "headshot_alt", "thesis_before", "thesis_accent", "thesis_after", "story_heading", "story_sub", "story_body", "outside_heading", "outside_sub", "photos", "principles_heading", "principles_sub", "principles", "currently_heading", "currently_sub", "currently_updated", "working_on", "booking", "reading", "learning", "testimonials_heading", "testimonials_sub", "lighthouse_performance", "lighthouse_accessibility", "lighthouse_best_practices", "lighthouse_seo", "job_title") VALUES ('01CIF6D4EE30DBE318273397CE', 'about', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CIF6D4EE30DBE318273397CE', 'About', 'About Nathan Nixon, sole owner of Nixon Creative Studio in Cincinnati, Ohio.', 'Want to talk about a project?', 'I take on a small number of projects each quarter. The earlier we talk, the easier it is to schedule the work.', 'A one-person studio for', 'organizations that take their work seriously.', 'I''m Nathan Nixon. I run Nixon Creative Studio out of Cincinnati, Ohio, and I work with small businesses, nonprofits, churches, and schools, in person around the region and anywhere for web work. I do the strategy, the design, the photography, and the code, so the person you meet on day one is the same person who hands you the finished site.', '{"id":"01CI6843011C9C322167FCE80E","provider":"local","filename":"headshot.jpg","mimeType":"image/jpeg","width":1200,"height":1200,"dominantColor":"rgb(24,24,8)","alt":"Nathan Nixon, smiling outdoors","meta":{"storageKey":"86F1DEF57F772F8603E443AA3C.jpg","dominantColor":"rgb(24,24,8)"}}', 'Nathan Nixon, smiling outdoors', 'One person on every project, start to finish: strategy, design, photography, and code. I work with', 'churches, schools, nonprofits, and small businesses', 'around Cincinnati in person, and anywhere for web work.', 'The longer story', 'From behind the camera to the web, and why one person handles all of it.', '[{"_type":"block","_key":"k1","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k0","text":"I came to this work through a camera. For years I photographed portraits, families, weddings, the events people most want to remember, and the part I loved was helping someone show up at their best. When the shoots dried up in 2020, I started building websites for a few of those same clients, and it turned out to be the same job in a new medium: work out what someone is really trying to say, then make it clear. Web design is the studio''s main work now, but the photographer''s eye stayed, and most projects still end up with real photography in them.","marks":[]}]},{"_type":"block","_key":"k3","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2","text":"Before any of that I studied mechanical engineering at the University of Edinburgh, back home in Scotland. The degree did not make me a designer, but it taught me to take a thing apart, understand why each piece is there, and put it back together so it holds. That is how I approach a website too: structure first, surface second, and built so the person who inherits it can actually keep it running.","marks":[]}]},{"_type":"block","_key":"k5","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k4","text":"I also do plenty of this work as a volunteer. I''m on the media team at Crestview Presbyterian Church, where I run the weekly livestream, plan and buy the equipment upgrades, and shoot the photo and video the church uses for its website and its socials.","marks":[]}]},{"_type":"block","_key":"k7","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k6","text":"Personally, I moved from Scotland to Cincinnati in 2017 to be with my wife, became a US citizen in 2022, and these days we''re raising two kids and buying our first house here. When I''m away from a screen I''m usually out on a long run, chasing landscapes with a camera, deep in an ambitious Lego build with the kids, or a few episodes into a history drama.","marks":[]}]}]', 'Outside the studio', 'A few snapshots from the rest of life around Cincinnati: family, the trails, and the occasional turn in front of the camera.', '[{"image":{"id":"01CIB9BADF1664BECE8DC96D3C","provider":"local","filename":"family.jpg","mimeType":"image/jpeg","width":720,"height":1080,"dominantColor":"rgb(200,216,232)","alt":"Nathan with his family on a picnic blanket in a park, a young child eating watermelon.","meta":{"storageKey":"05475499F30B1362C1A7C53590.jpg","dominantColor":"rgb(200,216,232)"}},"caption":"A park afternoon","alt":"Nathan with his family on a picnic blanket in a park, a young child eating watermelon."},{"image":{"id":"01CIB5CD2685EB8733ED776C3B","provider":"local","filename":"running.jpg","mimeType":"image/jpeg","width":1205,"height":1600,"dominantColor":"rgb(88,88,88)","alt":"Nathan and a friend at the end of a charity 5K, race bibs on, in a sunny parking lot.","meta":{"storageKey":"7CC6E780F896897BD4168DA97D.jpg","dominantColor":"rgb(88,88,88)"}},"caption":"Race day","alt":"Nathan and a friend at the end of a charity 5K, race bibs on, in a sunny parking lot."},{"image":{"id":"01CIFA6693DE03BDE379B848F8","provider":"local","filename":"exploring.jpg","mimeType":"image/jpeg","width":1200,"height":1600,"dominantColor":"rgb(8,8,8)","alt":"Nathan carrying a small child on a sunny day in front of old railroad cars.","meta":{"storageKey":"BA19E0CE98821EE10F469ED28E.jpg","dominantColor":"rgb(8,8,8)"}},"caption":"Out exploring","alt":"Nathan carrying a small child on a sunny day in front of old railroad cars."},{"image":{"id":"01CI05F6CBA56143D61A697473","provider":"local","filename":"wedding.jpg","mimeType":"image/jpeg","width":1079,"height":720,"dominantColor":"rgb(216,216,216)","alt":"Nathan and his wife laughing together on their wedding day, beside a lake.","meta":{"storageKey":"7E63C36BE4E127845E3D415F40.jpg","dominantColor":"rgb(216,216,216)"}},"caption":"Wedding day","alt":"Nathan and his wife laughing together on their wedding day, beside a lake."},{"image":{"id":"01CI8A214B586CD2D558FB04A5","provider":"local","filename":"portrait-bw.jpg","mimeType":"image/jpeg","width":1600,"height":1280,"dominantColor":"rgb(8,8,8)","alt":"A black-and-white studio portrait of Nathan looking off to the side.","meta":{"storageKey":"E8951EEC5A1B51303481379D99.jpg","dominantColor":"rgb(8,8,8)"}},"caption":"From the other side of the lens","alt":"A black-and-white studio portrait of Nathan looking off to the side."}]', 'How I work', 'Three principles that hold across every project, big or small.', '[{"title":"Strategy before pixels","body":"Every project starts with a working session and a one-page brief we both agree on. Design choices follow from there, not from whichever template looks freshest."},{"title":"The right platform for the job","body":"Some clients are best served by a custom-coded site, others by Squarespace or WordPress. I pick what fits your budget and the people who will maintain it, then set it up so the next volunteer or staff member can keep it running after I hand it over."},{"title":"Cincinnati base, clients anywhere","body":"Based in Cincinnati, so local clients meet in person and get on-site photography. Web design and strategy go wherever the client is, fully remote when that is easier. Short distance when it helps, no distance when it does not."}]', 'Currently', 'A present-tense snapshot of the studio: current work, what I''m reading, and what I''m trying to get sharper on. Rewritten every couple of months.', '2026-10-01', '[{"text":"Finishing the Presbyterian Academy website ahead of the school''s first term."},{"text":"Buying our first house, here in Cincinnati."}]', '[{"label":"Web design","status":"open","detail":"Open to new web design projects of every kind this quarter, from a single landing page to a full rebuild."},{"label":"Photography","status":"limited","detail":"A few shoot days each month, fit around the web work, for portraits, families, events, and the brand photography that pairs with a new site."}]', '[{"title":"John Adams","author":"David McCullough"},{"title":"The New Father","author":"Armin A. Brott"},{"title":"The Lord of the Rings","author":"J.R.R. Tolkien","note":"re-reading"}]', '[{"text":"Smoother, steadier video out of my gimbal"},{"text":"Coaxing a genuinely lush green lawn out of the backyard"},{"text":"Going deeper on Astro, the framework this very site runs on"}]', 'What clients say', 'Real words from the churches, schools, and businesses I''ve built for.', 92, 100, 100, 100, 'Founder, Designer, Developer, Photographer');
