INSERT OR REPLACE INTO ec_page_contact ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "cta_title", "cta_sub", "cta_label", "heading", "heading_accent", "intro", "budgets", "timelines", "heard_from", "next_steps", "where_text") VALUES ('01CI4560C6665D2911C1BE0877', 'contact', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI4560C6665D2911C1BE0877', 'Contact', 'Get in touch about a web design, brand, or photography project.', 'Rather skip the form?', 'Email or call me directly. A sentence about your project is enough to get started.', 'Email me', 'Start a project, or just', 'say hello.', 'The form sends straight to my inbox. If you''d rather email or call, those work just as well.', '[{"label":"Under $4,000"},{"label":"$4,000 to $7,000"},{"label":"$7,000 to $12,000"},{"label":"$12,000 or more"},{"label":"Not sure yet"}]', '[{"label":"Right away"},{"label":"In the next 1 to 3 months"},{"label":"3 to 6 months from now"},{"label":"More than 6 months out"},{"label":"Flexible, no fixed deadline"}]', '[{"label":"A referral from someone I know"},{"label":"Google or another search engine"},{"label":"Instagram, LinkedIn, or other social"},{"label":"I''ve worked with Nathan before"},{"label":"In person, at an event or through a church or school"},{"label":"Somewhere else"}]', '[{"text":"You send the form."},{"text":"I read it myself and reply within one or two business days."},{"text":"If we''re a fit, a half-hour call to talk it through."}]', 'In-person work and photography across the greater Cincinnati region; web design and strategy with clients anywhere, fully remote when that is easier.');
