INSERT OR REPLACE INTO ec_page_journal ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "heading", "intro", "empty_kicker", "empty_heading", "empty_body") VALUES ('01CI33E71BEAEE0A3495389719', 'journal', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI33E71BEAEE0A3495389719', 'Journal', 'Short essays, process notes, and field reports from the studio.', 'Journal', 'Short notes from the studio: process, opinions, the occasional field report. Updated whenever there''s something worth writing down.', 'First dispatch is coming.', 'The first entry is being drafted.', 'This is where I''ll write down how the studio works: the thinking behind a build, notes from a shoot, the small decisions that add up. Nothing''s published yet. While you wait, two good places to land.');
