INSERT OR REPLACE INTO ec_page_not_found ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "label", "heading", "body", "links") VALUES ('01CIE42BB8B1FA99EEA404E7DD', 'not-found', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CIE42BB8B1FA99EEA404E7DD', 'Page not found', 'That page wandered off. Here''s how to get back on track.', 'Page not found', 'That page wandered off.', 'The link you followed might be old, or the address might be a typo. Nothing''s broken on this end. Here are a few places to try instead.', '[{"label":"Back to home","href":"/"},{"label":"See selected work","href":"/work/"},{"label":"Get in touch","href":"/contact"}]');
