INSERT OR REPLACE INTO ec_page_work ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "eyebrow", "heading", "intro", "empty_filter_message", "live_heading", "live_body") VALUES ('01CI115CC811DED3D8E1D7930B', 'work', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI115CC811DED3D8E1D7930B', 'Selected work', 'A list of recent web design, brand, and photography projects from Nixon Creative Studio.', 'Portfolio', 'Selected work', 'for churches, schools, nonprofits, and small businesses around Cincinnati. Each one started with a conversation about what the organization actually needed.', 'Nothing matches that filter yet. Try clearing one of the chips above.', 'Open any of them', 'Every project here is a real, shipped site. Do not take my word for it, click through and look around.');
DELETE FROM ec_pages WHERE slug NOT IN ('privacy', 'accessibility', 'colophon');
INSERT OR REPLACE INTO ec_pages ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "heading", "eyebrow", "summary", "intro", "content", "show_toc", "last_updated") VALUES ('01CIEF5ED18B97437EF602F720', 'privacy', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CIEF5ED18B97437EF602F720', 'Privacy', 'What this site collects.', 'Privacy notice', 'What this site collects, and what it does with it.', '[{"_type":"block","_key":"k4","style":"normal","markDefs":[{"_key":"k1","_type":"link","href":"mailto:nathan@nixoncreativestudio.com"}],"children":[{"_type":"span","_key":"k0","text":"Short version: a contact form, two analytics tools (a cookieless Cloudflare beacon and Google Analytics), an embedded Google Map on the contact page, and the things any web server logs. No advertising trackers. If you have questions, email ","marks":[]},{"_type":"span","_key":"k2","text":"nathan@nixoncreativestudio.com","marks":["k1"]},{"_type":"span","_key":"k3","text":".","marks":[]}]}]', '[{"_type":"block","_key":"k1","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k0","text":"Contact form","marks":[]}]},{"_type":"block","_key":"k6","style":"normal","markDefs":[{"_key":"k3","_type":"link","href":"https://web3forms.com/"}],"children":[{"_type":"span","_key":"k2","text":"When you submit the form on the Contact page, the fields you fill in (your name, email, organization type, budget range, and project description) are sent through ","marks":[]},{"_type":"span","_key":"k4","text":"Web3Forms","marks":["k3"]},{"_type":"span","_key":"k5","text":" and delivered to my inbox. Web3Forms acts as the delivery pipe and does not retain submissions beyond the brief window needed to deliver them. I keep the email in my inbox the same way I''d keep any project inquiry.","marks":[]}]},{"_type":"block","_key":"k8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k7","text":"The form also includes a hidden \"honeypot\" field that real visitors never fill in. If a bot submits the form and trips the honeypot, the message is quietly discarded.","marks":[]}]},{"_type":"block","_key":"ka","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k9","text":"Analytics","marks":[]}]},{"_type":"block","_key":"kc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kb","text":"The site uses two analytics tools, and I use both for the same thing: to see which pages are useful and which aren''t.","marks":[]}]},{"_type":"block","_key":"kg","style":"normal","markDefs":[{"_key":"kd","_type":"link","href":"https://www.cloudflare.com/web-analytics/"}],"children":[{"_type":"span","_key":"ke","text":"Cloudflare Web Analytics","marks":["kd"]},{"_type":"span","_key":"kf","text":" counts page views and basic performance metrics without cookies, without fingerprinting, and without sending data to any third-party advertising network.","marks":[]}]},{"_type":"block","_key":"kn","style":"normal","markDefs":[{"_key":"kh","_type":"link","href":"https://support.google.com/analytics/answer/6004245"},{"_key":"kk","_type":"link","href":"https://tools.google.com/dlpage/gaoptout"}],"children":[{"_type":"span","_key":"ki","text":"Google Analytics 4","marks":["kh"]},{"_type":"span","_key":"kj","text":" records page views, scrolls, and outbound clicks, and sends them to Google. It sets first-party cookies to tell returning visits apart, and it truncates IP addresses before storing anything. I do not use it for advertising, I have not linked it to any ad account, and I have not turned on Google Signals or any demographic reporting. To opt out everywhere, install Google''s ","marks":[]},{"_type":"span","_key":"kl","text":"browser add-on","marks":["kk"]},{"_type":"span","_key":"km","text":"; most tracker-blocking extensions and browsers also stop it.","marks":[]}]},{"_type":"block","_key":"kp","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"ko","text":"Server logs","marks":[]}]},{"_type":"block","_key":"kr","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kq","text":"The hosting platform (Cloudflare Pages) records standard request data: IP address, user agent, requested URL, response code, timestamp. These logs are retained for a short window and used for operational purposes like blocking abuse and diagnosing errors. They are not used to build profiles of visitors.","marks":[]}]},{"_type":"block","_key":"kt","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"ks","text":"Cookies","marks":[]}]},{"_type":"block","_key":"kx","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"ku","text":"Google Analytics sets a small number of first-party cookies (the ","marks":[]},{"_type":"span","_key":"kv","text":"_ga","marks":["code"]},{"_type":"span","_key":"kw","text":" family) so it can tell a returning visit from a new one. They carry a random identifier, not your name or email, and the Analytics section above links the opt-out. The contact page also embeds a Google Map: when that map loads, Google may set its own cookies and receive your IP address, the same as if you visited Google Maps directly. Nothing else on the site sets cookies. If a future change adds more third-party content, this page will say so first.","marks":[]}]},{"_type":"block","_key":"kz","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"ky","text":"Your data","marks":[]}]},{"_type":"block","_key":"k14","style":"normal","markDefs":[{"_key":"k11","_type":"link","href":"mailto:nathan@nixoncreativestudio.com"}],"children":[{"_type":"span","_key":"k10","text":"If you''ve sent a project inquiry and want me to delete it from my inbox, email ","marks":[]},{"_type":"span","_key":"k12","text":"nathan@nixoncreativestudio.com","marks":["k11"]},{"_type":"span","_key":"k13","text":" with the email address you used to send it. I''ll confirm when it''s deleted.","marks":[]}]},{"_type":"block","_key":"k16","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k15","text":"Changes","marks":[]}]},{"_type":"block","_key":"k18","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17","text":"If what the site collects changes, I''ll update this page and bump the date at the bottom. There''s no separate notification list for privacy updates.","marks":[]}]}]', 1, '2026-09-04');
INSERT OR REPLACE INTO ec_pages ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "heading", "eyebrow", "summary", "intro", "content", "show_toc", "last_updated") VALUES ('01CI1C89B4ACB4E77B8F6D1074', 'accessibility', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI1C89B4ACB4E77B8F6D1074', 'Accessibility', 'Built to be used by everyone.', 'Accessibility', 'How this site is built for keyboard and screen-reader users, how it''s tested, and how to report a problem.', '[{"_type":"block","_key":"k4","style":"normal","markDefs":[{"_key":"k1","_type":"link","href":"mailto:nathan@nixoncreativestudio.com"}],"children":[{"_type":"span","_key":"k0","text":"I build this site toward WCAG 2.1 AA, in both the light and the dark theme, and I check it on every change. No website is ever perfectly accessible, so if anything is hard to use with a keyboard or a screen reader, tell me and I''ll fix it: ","marks":[]},{"_type":"span","_key":"k2","text":"nathan@nixoncreativestudio.com","marks":["k1"]},{"_type":"span","_key":"k3","text":".","marks":[]}]}]', '[{"_type":"block","_key":"k1","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k0","text":"The standard","marks":[]}]},{"_type":"block","_key":"k3","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2","text":"The goal is WCAG 2.1 AA, the same standard most public bodies and larger organizations are held to, and it applies in both the light and the dark theme. Each page is built to score 100 on Lighthouse''s accessibility audit, and an automated check runs on every change so that score does not quietly slip. That automated score is a useful floor, not a certificate: it catches the machine-checkable issues, which are only one part of the picture.","marks":[]}]},{"_type":"block","_key":"k5","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k4","text":"In practice","marks":[]}]},{"_type":"block","_key":"k7","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k6","text":"A few of the things that means on this site:","marks":[]}]},{"_type":"block","_key":"k9","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k8","text":"Everything you can do with a mouse, you can do with a keyboard. The focus outline is always visible, and a \"Skip to main content\" link is the first thing you reach.","marks":[]}]},{"_type":"block","_key":"kb","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ka","text":"Real landmarks and a clean heading order, so a screen reader can move through a page by region and by heading instead of reading it all top to bottom.","marks":[]}]},{"_type":"block","_key":"kd","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"kc","text":"Every form field has a visible label, uses the right input type, and announces its own errors rather than signalling them with color alone.","marks":[]}]},{"_type":"block","_key":"kf","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ke","text":"Text is chosen to clear the AA contrast bar against its background in both the light and the dark theme. Images that carry meaning have descriptions; purely decorative ones are hidden from assistive tech.","marks":[]}]},{"_type":"block","_key":"kh","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"kg","text":"If your device is set to reduce motion, the animations and the smooth scrolling switch off automatically.","marks":[]}]},{"_type":"block","_key":"kj","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"ki","text":"How it is checked","marks":[]}]},{"_type":"block","_key":"ko","style":"normal","markDefs":[{"_key":"kl","_type":"link","href":"https://github.com/dequelabs/axe-core"}],"children":[{"_type":"span","_key":"kk","text":"The accessibility score is a hard gate: a change cannot ship if it drops a page below 100. On top of that, the pages are run through ","marks":[]},{"_type":"span","_key":"km","text":"axe-core","marks":["kl"]},{"_type":"span","_key":"kn","text":" (a widely used accessibility testing engine) in both themes, and structural changes get a manual keyboard pass from the address bar through every control. Automated tools like these only cover part of WCAG; the rest is judgment, whether the alt text is actually useful, whether the reading order makes sense, so I treat the tooling as a safety net under the hands-on work, not a stand-in for it.","marks":[]}]},{"_type":"block","_key":"kq","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"kp","text":"Where it stops short","marks":[]}]},{"_type":"block","_key":"ks","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kr","text":"I aim for AA, not the stricter AAA, on purpose, in line with the W3C''s own guidance that AAA is not meant as a blanket requirement for a whole site. A couple of AAA rules pull against a brand-led design: the deepest brand-blue text sits just under the 7:1 enhanced-contrast bar, for one. So the work targets AA and stops there by choice, not by oversight.","marks":[]}]},{"_type":"block","_key":"ku","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kt","text":"That is a line about polish, not about whether the site works. If a specific thing is genuinely hard for you to use, that is a bug, and the next section is how to flag it.","marks":[]}]},{"_type":"block","_key":"kw","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"kv","text":"Found a problem?","marks":[]}]},{"_type":"block","_key":"k11","style":"normal","markDefs":[{"_key":"ky","_type":"link","href":"mailto:nathan@nixoncreativestudio.com"}],"children":[{"_type":"span","_key":"kx","text":"If a page is hard to read, hard to get through, or breaks with the assistive technology you rely on, email ","marks":[]},{"_type":"span","_key":"kz","text":"nathan@nixoncreativestudio.com","marks":["ky"]},{"_type":"span","_key":"k10","text":" and tell me what happened and what you were using. It reaches a real person, me, and I treat accessibility problems as real problems to fix, not as nice-to-haves.","marks":[]}]}]', 1, '2026-06-27');
INSERT OR REPLACE INTO ec_pages ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "heading", "summary", "intro", "rows", "show_toc") VALUES ('01CI7D3A2ED3DABA76180E80E7', 'colophon', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI7D3A2ED3DABA76180E80E7', 'Colophon', 'Colophon', 'How this site is built: the tools, the type, and the accessibility and privacy standards behind it.', '[{"_type":"block","_key":"k1","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k0","text":"How this site is made, and the standards behind it. Custom-built, so the same care that goes into client work goes into my own.","marks":[]}]}]', '[{"label":"Built with","detail":"Custom-coded in Astro with TypeScript, styled with Tailwind CSS, and deployed to Cloudflare. No page builder, no stock template, no lock-in."},{"label":"Typography","detail":"Headings are set in Bebas Neue and everything else in Source Sans 3, both self-hosted so nothing loads from a third party."},{"label":"Accessibility","detail":"Built toward WCAG AA and checked automatically on every deploy. In plain terms: it works with a keyboard, with a screen reader, and in light or dark. There is a fuller statement on the accessibility page."},{"label":"Performance","detail":"Pages are put together on the Cloudflare network and then kept in a cache close to each visitor, images are resized to fit the screen, and the fonts ship with the site, so it stays fast on a phone and a slow connection."},{"label":"Photography","detail":"Every photograph on the site was shot by Nathan."},{"label":"Privacy","detail":"Privacy-friendly analytics, no advertising trackers, and nothing following you from page to page."}]', 0);
