INSERT OR REPLACE INTO ec_posts ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "excerpt", "featured_image", "updated", "content") VALUES ('01CI13CC42CB85F8F6D5089530', 'ci-test-entry', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI13CC42CB85F8F6D5089530', 'A CI test journal entry', 'A stand-in entry used only by the CI dataset, so the journal list and the entry page render and are checked for accessibility.', '{"id":"01CI734122478271199E4E5A49","provider":"local","filename":"events-01.jpg","mimeType":"image/jpeg","width":1600,"height":1200,"dominantColor":"rgb(40,104,152)","alt":"A sample frame used only by the CI dataset","meta":{"storageKey":"07D2959E0A7C0FD4C41C791AF7.jpg","dominantColor":"rgb(40,104,152)"}}', '2026-10-04T12:00:00.000Z', '[{"_type":"block","_key":"ci-p1","style":"normal","markDefs":[{"_key":"ci-l1","_type":"link","href":"https://example.com/"}],"children":[{"_type":"span","_key":"ci-s1","text":"This entry exists so the ","marks":[]},{"_type":"span","_key":"ci-s2","text":"journal","marks":["strong"]},{"_type":"span","_key":"ci-s3","text":" has something to draw. It carries a ","marks":[]},{"_type":"span","_key":"ci-s4","text":"link","marks":["ci-l1"]},{"_type":"span","_key":"ci-s5","text":", some emphasis, a list, a quote and a code block.","marks":[]}]},{"_type":"block","_key":"ci-h2","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"ci-s6","text":"A section heading","marks":[]}]},{"_type":"block","_key":"ci-p2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"ci-s7","text":"Paragraphs under a heading keep the reading rhythm of the page. The list below has two items.","marks":[]}]},{"_type":"block","_key":"ci-li1","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ci-s8","text":"The first item","marks":[]}]},{"_type":"block","_key":"ci-li2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ci-s9","text":"The second item","marks":[]}]},{"_type":"block","_key":"ci-q1","style":"blockquote","markDefs":[],"children":[{"_type":"span","_key":"ci-s10","text":"A quote is set apart from the body.","marks":[]}]},{"_type":"code","_key":"ci-code1","language":"ts","code":"const greeting = ''hello'';"},{"_type":"block","_key":"ci-h3","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"ci-s11","text":"A subsection","marks":[]}]},{"_type":"block","_key":"ci-p3","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"ci-s12","text":"The end of the entry.","marks":[]}]}]');
INSERT OR REPLACE INTO ec_posts ("id", "slug", "status", "created_at", "updated_at", "version", "locale", "translation_group", "title", "excerpt", "content") VALUES ('01CI6364124A41FF57104A5B53', 'ci-draft-entry', 'draft', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI6364124A41FF57104A5B53', 'A CI draft journal entry that must never be visible', 'If this text appears anywhere on the public site, a draft has leaked: the journal list, the entry page, the feed and the sitemap must all leave it out.', '[{"_type":"block","_key":"ci-dp1","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"ci-ds1","text":"This is a draft body.","marks":[]}]}]');
