INSERT OR REPLACE INTO ec_pricing_addons ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price", "note", "sort_order") VALUES ('01CI03F0C6D1978E7E7AD25DE8', 'photography', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI03F0C6D1978E7E7AD25DE8', 'Photography', 'from $900', 'Headshots, brand, and environmental photos shot for your site by the person who designed it. A half-day starts at $900 and a full day runs about $1,200, often folded into a build or booked on its own across the Cincinnati region.', 1);
INSERT OR REPLACE INTO ec_pricing_addons ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price", "note", "sort_order") VALUES ('01CI0AAC43222F1920B5943367', 'brand-strategy', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI0AAC43222F1920B5943367', 'Brand & strategy', '$500 to $2,000', 'Standalone strategy or brand-identity work for when you need it on its own. Strategy is already built into every website project.', 2);
INSERT OR REPLACE INTO ec_pricing_addons ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price", "note", "sort_order") VALUES ('01CI6643550FB8739DDB3BC2D4', 'care-plan', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI6643550FB8739DDB3BC2D4', 'Care plan', 'from $100/mo', 'Optional. Updates, backups, security, and, on the higher tiers, a monthly bucket of small content edits. It does not cover major revisions or new features, which are quoted separately. Skip it and the site is still yours to leave alone for years, with no lock-in.', 3);
DELETE FROM ec_pricing_tiers WHERE slug NOT IN ('launch', 'signature', 'flagship');
INSERT OR REPLACE INTO ec_pricing_tiers ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price_from", "price_suffix", "who", "range", "note", "features", "highlighted", "sort_order") VALUES ('01CIE4B1B487667A56E6DED974', 'launch', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CIE4B1B487667A56E6DED974', 'Launch', 4000, '+', 'Smaller organizations', 'Most land between $4,000 and $6,500', 'A focused custom site for a smaller organization: the essential pages done well, with content you can keep current yourself. The right fit when you want a clear, strong presence without a lot of moving parts.', '[{"text":"A focused set of core pages, designed around your goals"},{"text":"Content you can keep current yourself"},{"text":"Accessible and fast, set up and handed off"}]', 0, 1);
INSERT OR REPLACE INTO ec_pricing_tiers ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price_from", "price_suffix", "who", "range", "note", "features", "highlighted", "badge", "sort_order") VALUES ('01CI8EA3C2DC72783758A801AB', 'signature', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI8EA3C2DC72783758A801AB', 'Signature', 7000, '+', 'Most projects', 'Most land between $7,000 and $11,000', 'The right fit for most projects: a larger custom site with deeper content, several content types your team manages itself, and the integrations a growing church, school, or business needs.', '[{"text":"A larger site with deeper content sections"},{"text":"Several content types your team manages itself"},{"text":"Integrations and search-engine work built in"}]', 1, 'Where most projects land', 2);
INSERT OR REPLACE INTO ec_pricing_tiers ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price_from", "price_suffix", "who", "range", "note", "features", "highlighted", "sort_order") VALUES ('01CI31FAD2736752DFADAF1AB0', 'flagship', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI31FAD2736752DFADAF1AB0', 'Flagship', 12000, '+', 'Advanced builds', 'Typically $12,000 and up', 'For organizations that need the site to do real work: custom interactive tools, advanced integrations, or a headless build for a large, complex site. The kind of build an agency would charge far more for.', '[{"text":"Custom interactive tools and features"},{"text":"Advanced and third-party integrations"},{"text":"A headless build for a large, deep site"}]', 0, 3);
DELETE FROM ec_service_offerings WHERE slug NOT IN ('strategy', 'web-design', 'photography');
INSERT OR REPLACE INTO ec_service_offerings ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "lede", "body", "price_from", "placeholder_icon", "points", "area_served", "sort_order") VALUES ('01CIA55B45731FF985CE7D7025', 'strategy', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CIA55B45731FF985CE7D7025', 'Strategy', 'The planning work that decides what the site is for, who it serves, and how it earns its keep.', 'Strategy always comes first. Without it, design becomes decoration. We start with a working session, then I write a short brief that the rest of the project follows.', 1500, 'strategy', '[{"text":"A working session, then back-and-forth until the plan is right"},{"text":"Audience map and conversion path"},{"text":"Content inventory of what you already have"},{"text":"A one-page brief the rest of the project follows"}]', 'anywhere', 1);
INSERT OR REPLACE INTO ec_service_offerings ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "lede", "body", "image_alt", "placeholder_icon", "points", "area_served", "sort_order") VALUES ('01CI21225C884B4B0C7AF4A5F1', 'web-design', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI21225C884B4B0C7AF4A5F1', 'Web design', 'Modern, accessible, fast websites built on the platform that fits you, from a custom-coded site to Squarespace or WordPress, and set up so your team can actually run it.', 'I match the build to your budget and to whoever will maintain it after launch. Everything is built mobile-first and tested for accessibility from the very first screen, then handed off so you are never locked out of your own site.', 'The Second Presbyterian Church of Chicago website, designed and built by the studio', 'none', '[{"text":"A custom design built to your brand, not a stock template"},{"text":"Self-hosted typography and imagery"},{"text":"Mobile-first responsive layouts"},{"text":"WCAG-aware accessibility from day one"},{"text":"Deployed to Cloudflare Pages, auto-rebuild on every commit"}]', 'anywhere', 2);
INSERT OR REPLACE INTO ec_service_offerings ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "lede", "body", "price_from", "placeholder_icon", "points", "area_served", "sort_order") VALUES ('01CIA22669325146AA495E9DD0', 'photography', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CIA22669325146AA495E9DD0', 'Photography', 'Headshots, event coverage, and environmental photography shot for your website by the same person who designed it.', 'When the photographer and the designer are one person, the photos match the layout instead of fighting it. Images arrive edited, web-optimized, and ready to drop in.', 900, 'photography', '[{"text":"On-site Sunday or weekday coverage"},{"text":"Headshots for team and staff"},{"text":"Environmental photography of your space"},{"text":"Edited, web-optimized images delivered with the website"}]', 'regional', 3);
