INSERT OR REPLACE INTO ec_site_settings ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "studio_name", "owner_name", "email", "phone", "location", "tagline", "instagram_url", "linkedin_url", "header_cta_label", "footer_currently", "cta_default_title", "cta_default_sub", "cta_default_label", "default_description", "rss_title", "rss_description") VALUES ('01CIBD37DE2690DC59938CA0FB', 'site', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CIBD37DE2690DC59938CA0FB', 'Nixon Creative Studio', 'Nathan Nixon', 'nathan@nixoncreativestudio.com', '(256) 318-6627', 'Cincinnati, OH', 'Modern websites for small businesses, nonprofits, churches, and schools. Based in Cincinnati, working with clients anywhere.', 'https://www.instagram.com/thenate_n/', 'https://www.linkedin.com/in/nathannixon/', 'Start a project', 'Booking small business and nonprofit web projects for the season ahead, with a few photography days mixed in.', 'Let''s build a site you won''t have to redo.', 'I take a small number of projects each quarter. The earlier we talk, the better we can pace it together.', 'Start a project', 'Nixon Creative Studio', 'Nixon Creative Studio — Case Studies', 'Modern websites for small businesses, nonprofits, churches, and schools. Based in Cincinnati, working with clients anywhere.');
